"""Generate the SLO & error-budget dashboard from pyrra-slo-money-path.yaml.

WHY: dashboard-openbank-slo.yaml hardcoded a four-service regex (sepa-payment, domestic-payment,
sepa-instant, fx) while the Pyrra file declares an SLO pair for every money-path service (28 at
the time of writing). 24 services had an error budget in Pyrra and no panel anywhere. The service
set and the targets are now READ from the Pyrra file, which check-slo-registry.py already holds to
rules.yaml, so the dashboard cannot name a different set than the objects it visualises.

Output: openbank-infra/gitops/components/observability/dashboard-openbank-slo.yaml (derived; never
hand-edit). The three fleet panels come from slo-dashboard-base.json (their `rail` variable is the
derived regex); one availability stat per service is appended, thresholded on that service's own
target.

Usage:
  python3 .github/scripts/gen-slo-dashboard.py            # write
  python3 .github/scripts/gen-slo-dashboard.py --check    # exit 1 when the committed file differs
  python3 .github/scripts/gen-slo-dashboard.py --self-test
"""
from __future__ import annotations

import json
import pathlib
import sys

import yaml

REPO = pathlib.Path(__file__).resolve().parents[2]
OBS = REPO / "openbank-infra" / "gitops" / "components" / "observability"
SOURCE = OBS / "pyrra-slo-money-path.yaml"
OUTPUT = OBS / "dashboard-openbank-slo.yaml"
BASE = pathlib.Path(__file__).resolve().parent / "slo-dashboard-base.json"
SERVICE_LABEL = "openbank.io/money-path-service"
COLUMNS = 4
PANEL_W = 24 // COLUMNS
PANEL_H = 5
FLEET_ROWS_HEIGHT = 16  # y offset below the three fleet panels in the base

HEADER = """\
# GENERATED by .github/scripts/gen-slo-dashboard.py from pyrra-slo-money-path.yaml - do not hand-edit.
# SLO & error-budget dashboard for every money-path service (ADR-0082, ADR-0077 Phase 4).
# Availability is derived from span-metrics (traces_spanmetrics_calls_total) so it needs no extra
# instrumentation. The SLO target is a dashboard variable; the rail filter is the set of services
# that have a Pyrra ServiceLevelObjective, derived from that file. Burn-rate panels mirror the
# multi-window alerts Pyrra reconciles. One stat per service below the fleet panels is thresholded
# on that service's own availability target.
# `or (denominator * 0)` keeps per-service labels so the ratio division matches by label set when
# a window has zero errors (a bare `or vector(0)` has no `service` label and cannot match).
# Regenerate: python3 .github/scripts/gen-slo-dashboard.py
"""


def load_services(path: pathlib.Path = SOURCE) -> list[dict]:
    """[{service, availability_target, latency_target}] sorted by service, from the Pyrra file."""
    found: dict[str, dict] = {}
    for doc in yaml.safe_load_all(path.read_text(encoding="utf-8")):
        if not doc or doc.get("kind") != "ServiceLevelObjective":
            continue
        service = doc["metadata"]["labels"].get(SERVICE_LABEL)
        if not service:
            raise SystemExit(f"{doc['metadata']['name']}: missing label {SERVICE_LABEL}")
        entry = found.setdefault(service, {"service": service})
        kind = "availability_target" if "ratio" in doc["spec"]["indicator"] else "latency_target"
        entry[kind] = float(doc["spec"]["target"])
    for entry in found.values():
        missing = {"availability_target", "latency_target"} - entry.keys()
        if missing:
            raise SystemExit(f"{entry['service']}: Pyrra file lacks {sorted(missing)}")
    return [found[k] for k in sorted(found)]


def rail_regex(services: list[dict]) -> str:
    return "(" + "|".join(s["service"] for s in services) + ")"


def service_panel(panel_id: int, index: int, svc: dict) -> dict:
    name = svc["service"]
    target = svc["availability_target"] / 100
    sel = f'service=\\"{name}\\",span_kind=\\"SPAN_KIND_SERVER\\",span_name!~\\"GET /|GET /api/v1/info\\"'
    # Ratio of increase() values over the window, with NO denominator clamp: clamp_min(..., 0.001)
    # on a rate is ~0.001 calls/s ~ 2,600 calls per 30d, so a low-traffic service (1 error in 4
    # calls) showed ~98.8% instead of 75%. An empty denominator must render "No data" instead.
    denom = f"sum(increase(traces_spanmetrics_calls_total{{{sel}}}[30d]))"
    errors = f"sum(increase(traces_spanmetrics_calls_total{{{sel},status_code=\\\"STATUS_CODE_ERROR\\\"}}[30d]))"
    expr = f"1 - ( ( {errors} or ( {denom} * 0 ) ) / {denom} )"
    return {
        "id": panel_id,
        "title": name.removeprefix("openbank-"),
        "description": (
            f"30d availability, customer traffic only. SLO: {svc['availability_target']}% availability, "
            f"{svc['latency_target']}% under 1s."
        ),
        "type": "stat",
        "gridPos": {"x": (index % COLUMNS) * PANEL_W, "y": FLEET_ROWS_HEIGHT + (index // COLUMNS) * PANEL_H,
                    "w": PANEL_W, "h": PANEL_H},
        "datasource": {"type": "prometheus", "uid": "${datasource}"},
        "fieldConfig": {"defaults": {"unit": "percentunit", "min": 0, "max": 1, "thresholds": {
            "mode": "absolute",
            "steps": [{"color": "red", "value": None}, {"color": "green", "value": target}]}},
            "overrides": []},
        "options": {"reduceOptions": {"calcs": ["lastNotNull"]}, "colorMode": "background", "graphMode": "none"},
        "targets": [{"expr": expr.replace('\\"', '"'), "legendFormat": name, "refId": "A"}],
    }


def render(services: list[dict], base: dict | None = None) -> str:
    base = base if base is not None else json.loads(BASE.read_text(encoding="utf-8"))
    templating = json.loads(json.dumps(base["templating"]).replace("__RAIL_REGEX__", rail_regex(services)))
    panels = list(base["panels"])
    next_id = max(p["id"] for p in panels) + 1
    panels += [service_panel(next_id + i, i, s) for i, s in enumerate(services)]
    dashboard = {
        "id": None,
        "uid": "openbank-slo",
        "title": "OpenBank — Money-Path SLO & Error Budget",
        "schemaVersion": 39,
        "version": 1,
        "refresh": "1m",
        "time": {"from": "now-30d", "to": "now"},
        "templating": templating,
        "panels": panels,
    }
    body = json.dumps(dashboard, indent=2, ensure_ascii=False)
    indented = "\n".join("    " + line if line else line for line in body.splitlines())
    return (
        HEADER
        + "apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: dashboard-openbank-slo\n  namespace: observability\n"
        + '  labels:\n    grafana_dashboard: "1"\ndata:\n  openbank-slo.json: |\n'
        + indented
        + "\n"
    )


def self_test() -> int:
    failures = []

    def expect(name: str, cond: bool) -> None:
        print(("self-test ok: " if cond else "SELF-TEST FAIL: ") + name)
        if not cond:
            failures.append(name)

    services = [
        {"service": "openbank-a-service", "availability_target": 99.9, "latency_target": 99.0},
        {"service": "openbank-b-service", "availability_target": 99.5, "latency_target": 99.0},
    ]
    out = render(services)
    doc = yaml.safe_load(out)
    dash = json.loads(doc["data"]["openbank-slo.json"])
    rail = next(v for v in dash["templating"]["list"] if v["name"] == "rail")["query"]
    expect("rail regex lists exactly the declared services", rail == "(openbank-a-service|openbank-b-service)")
    expect("one stat panel per service on top of the fleet panels",
           len(dash["panels"]) == len(json.loads(BASE.read_text())["panels"]) + 2)
    expect("panel threshold is the service's own target",
           dash["panels"][-1]["fieldConfig"]["defaults"]["thresholds"]["steps"][1]["value"] == 0.995)
    expr = dash["panels"][-1]["targets"][0]["expr"]
    expect("per-service availability has no clamp_min denominator floor", "clamp_min" not in expr)
    expect("per-service availability compares increase() values", expr.count("increase(") == 3 and "rate(" not in expr)
    fleet = [p for p in dash["panels"][:-2] if p.get("targets")]
    fleet_exprs = [tg["expr"] for p in fleet for tg in p["targets"] if "traces_spanmetrics" in tg.get("expr", "")]
    expect("fleet panels exist and none uses clamp_min", bool(fleet_exprs) and all("clamp_min" not in x for x in fleet_exprs))
    expect("every fleet selector is SERVER-span and probe-excluding",
           all(x.count("traces_spanmetrics_calls_total{") == x.count('span_kind="SPAN_KIND_SERVER"')
               == x.count('span_name!~"GET /|GET /api/v1/info"') for x in fleet_exprs))
    expect("a new service changes the output (the gate can fail)", render(services[:1]) != out)
    real = load_services()
    expect("the real Pyrra file yields more services than the old four-rail regex",
           len(real) > 4 and all("availability_target" in s for s in real))
    return 1 if failures else 0


def main(argv: list[str]) -> int:
    if "--self-test" in argv:
        return self_test()
    services = load_services()
    wanted = render(services)
    if "--check" in argv:
        current = OUTPUT.read_text(encoding="utf-8") if OUTPUT.exists() else ""
        if current != wanted:
            print(f"::error::{OUTPUT.relative_to(REPO)} is stale against {SOURCE.name}. "
                  "Run: python3 .github/scripts/gen-slo-dashboard.py")
            return 1
        print(f"SUBJECTS={len(services)}  # money-path services with a dashboard panel")
        print("slo dashboard is in sync")
        return 0
    OUTPUT.write_text(wanted, encoding="utf-8")
    print(f"wrote {OUTPUT.relative_to(REPO)} ({len(services)} services)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
